data.grammar_fragment:
expr<text>
  : <0.5> XMLSERIALIZE "(" (DOCUMENT | CONTENT) XMLPARSE "(" (DOCUMENT | CONTENT) expr<text> xml_space?0.4 ")" AS "text" INDENT?0.4 ")"
  | <0.3> "(" XMLPARSE "(" CONTENT expr<text> ")" "::" "text" ")"
  ;

xml_space : PRESERVE WHITESPACE | STRIP WHITESPACE ;

expr<bool>
  : <0.4> "(" "(" expr<text> "::xml" ")" IS NOT?0.3 DOCUMENT ")"
  | <0.3> "(" XML_IS_WELLFORMED_CONTENT "(" expr<text> ")" ")"
  | <0.3> "(" XML_IS_WELLFORMED_DOCUMENT "(" expr<text> ")" ")"
  ;
